// App 컴포넌트를 default export로 유지
function App() {
    return (
        <HelmetProvider>
            <Router>
                <TopNav />
                <Routes>
                    <Route path="/" element={<MyApps />} />
                    <Route path="/Apps" element={<MyApps />} />
                    <Route path="/RemoveEmptyLines" element={<RemoveEmptyLines />} />
                    <Route path="/CodingHelper" element={<CodingHelper />} />
                    <Route path="/TextHelper" element={<TextHelper />} />
                    <Route path="/TextDiffViewer" element={<TextDiffViewer />} />
                    <Route path="/TextConverter" element={<TextConverter />} />
                    <Route path="/HomeMain" element={<HomeMain />} />
                    {/* <Route path="/Homepage" element={<Homepage />} /> */}
                    {/* <Route path="/MyHome" element={<MyHome />} /> */}
                    <Route path="/Velog" element={<Velog />} />
                    <Route path="/Map" element={<Map />} />
                    <Route path="/Waiting" element={<Waiting />} />
                    {/* <Route path="/Join" element={<Join />} /> */}
                    {/* <Route path="/LoginForm" element={<LoginForm />} */}
                    <Route path="/Curriculum" element={<Curriculum />} />
                    <Route path="/Language" element={<Language />} />
                    <Route path="/Textbook" element={<Textbook />} />
                    <Route path="/Progress" element={<Progress />} />
                    <Route path="/Project" element={<Project />} />
                </Routes>
                <Footer name="HYERIM" />
                <Aside />
            </Router>
        </HelmetProvider>
    );
}

export default App;