import React, { useState } from "react";
import Box from "@mui/material/Box";
import Typography from "@mui/material/Typography";
import ToggleButton from "@mui/material/ToggleButton";
import FormControl from "@mui/material/FormControl";
import Textarea from "@mui/joy/Textarea";
import IconButton from "@mui/material/IconButton";
import Tooltip from "@mui/material/Tooltip";
import Stack from "@mui/material/Stack";
import { Helmet } from 'react-helmet-async';
import RadioGroup from '@mui/material/RadioGroup';
import FormControlLabel from '@mui/material/FormControlLabel';
import Radio from '@mui/material/Radio';

import ContentCopyIcon from "@mui/icons-material/ContentCopy";
import RestartAltIcon from "@mui/icons-material/RestartAlt";
import DownloadIcon from "@mui/icons-material/Download";

import ReactDiffViewer, { DiffMethod } from "react-diff-viewer-continued";
import styles from '../css/TextDiffViewer.module.css';

const TextDiffViewer = () => {
  const [oldCode, setOldCode] = useState("");
  const [newCode, setNewCode] = useState("");
  const [splitView, setSplitView] = useState(true);
  const [diffMethod, setDiffMethod] = useState(DiffMethod.CHARS);

  const copyToClipboard = (text) => {
    navigator.clipboard.writeText(text);
  };

  const downloadText = (text, filename) => {
    const blob = new Blob([text], { type: "text/plain" });
    const link = document.createElement("a");
    link.download = filename;
    link.href = URL.createObjectURL(blob);
    link.click();
    URL.revokeObjectURL(link.href);
  };

  return (
    <div className={styles.background}>
          <div className={styles.title}>
        <h1>텍스트 비교</h1>
      </div>
    <Box className={styles.container}>
      <Helmet>
        <title>텍스트 비교 - 개발자 라이프</title>
      </Helmet>


      <div className={styles.controls}>
<ToggleButton
  className={styles.toggleButton}
  value="check"
  selected={splitView}
  onChange={() => setSplitView(!splitView)}
  sx={{ borderColor: 'gray.300', color: 'text.primary' }}
>
  {splitView ? (
    <>
      분할 보기
    </>
  ) : (
    <>
      통합 보기
    </>
  )}
</ToggleButton>


        <FormControl component="fieldset">
          <RadioGroup
            row
            name="diff-method"
            value={diffMethod}
            onChange={(e) => setDiffMethod(e.target.value)}
          >
            <FormControlLabel 
              value="diffChars" 
              control={
                <Radio 
                  size="small" 
                  sx={{
                    color: '#757575',
                    '&.Mui-checked': {
                      color: '#333333',
                    }
                  }}
                />
              } 
              label="문자 단위" 
            />
            <FormControlLabel 
              value="diffWords" 
              control={
                <Radio 
                  size="small"
                  sx={{
                    color: '#757575',
                    '&.Mui-checked': {
                      color: '#333333',
                    }
                  }}
                />
              } 
              label="단어 단위" 
            />
            <FormControlLabel 
              value="diffWordsWithSpace" 
              control={
                <Radio 
                  size="small"
                  sx={{
                    color: '#757575',
                    '&.Mui-checked': {
                      color: '#333333',
                    }
                  }}
                />
              } 
              label="단어+공백" 
            />
            <FormControlLabel 
              value="diffLines" 
              control={
                <Radio 
                  size="small"
                  sx={{
                    color: '#757575',
                    '&.Mui-checked': {
                      color: '#333333',
                    }
                  }}
                />
              } 
              label="줄 단위" 
            />
            <FormControlLabel 
              value="diffTrimmedLines" 
              control={
                <Radio 
                  size="small"
                  sx={{
                    color: '#757575',
                    '&.Mui-checked': {
                      color: '#333333',
                    }
                  }}
                />
              } 
              label="줄(공백 제거)" 
            />
            <FormControlLabel 
              value="diffSentences" 
              control={
                <Radio 
                  size="small"
                  sx={{
                    color: '#757575',
                    '&.Mui-checked': {
                      color: '#333333',
                    }
                  }}
                />
              } 
              label="문장 단위" 
            />
            <FormControlLabel 
              value="diffCss" 
              control={
                <Radio 
                  size="small"
                  sx={{
                    color: '#757575',
                    '&.Mui-checked': {
                      color: '#333333',
                    }
                  }}
                />
              } 
              label="CSS 단위" 
            />
          </RadioGroup>
        </FormControl>
      </div>

      <Box
        className={styles.textareaContainer}
        sx={{
          m: 1,
          display: "flex",
          flexDirection: "row",
          justifyContent: "space-between",
          gap: 2,
        }}
      >
        {/* 왼쪽 */}
        <Box sx={{ width: "50%" }}>
          <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            {/* 왼쪽 제목 */}
<Typography 
  variant="subtitle1" 
  sx={{ 
    color: '#ff4d4f',
    fontSize: '20px',
    fontWeight: 500
  }}
>
  📄 변경 전 텍스트 / 참고용 코드
</Typography>
            <Stack direction="row" spacing={1}>
              <Tooltip 
                title="복사" 
                placement="bottom"
                enterDelay={200}
                leaveDelay={0}
                arrow
                PopperProps={{
                  modifiers: [
                    {
                      name: 'offset',
                      options: {
                        offset: [0, 8],
                      },
                    },
                  ],
                }}
              >
                <IconButton onClick={() => copyToClipboard(oldCode)}>
                  <ContentCopyIcon fontSize="small" />
                </IconButton>
              </Tooltip>
              <Tooltip title="초기화">
                <IconButton onClick={() => setOldCode("")}>
                  <RestartAltIcon fontSize="small" />
                </IconButton>
              </Tooltip>
              <Tooltip title="다운로드">
                <IconButton onClick={() => downloadText(oldCode, "참고코드.txt")}>
                  <DownloadIcon fontSize="small" />
                </IconButton>
              </Tooltip>
            </Stack>
          </Box>
          <Textarea
            name="Old"
            placeholder="참고할 코드를 여기에 입력하세요..."
            variant="outlined"
            color="danger" // primary에서 danger로 변경
            minRows={15}
            maxRows={15}
            value={oldCode}
            onChange={(e) => setOldCode(e.target.value)}
            sx={{
              '--Textarea-focusedHighlight': '#ff4d4f',
              '--Textarea-focusedThickness': '2px',
              borderColor: '#ffccc7',
            }}
          />
        </Box>

        {/* 오른쪽 */}
        <Box sx={{ width: "50%" }}>
          <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            {/* 오른쪽 제목 */}
<Typography 
  variant="subtitle1"
  sx={{ 
    color: '#52c41a',
    fontSize: '20px',
    fontWeight: 500
  }}
>
  ✏️ 변경 후 텍스트 / 나의 코드
</Typography>
            <Stack direction="row" spacing={1}>
              <Tooltip title="복사">
                <IconButton onClick={() => copyToClipboard(newCode)}>
                  <ContentCopyIcon fontSize="small" />
                </IconButton>
              </Tooltip>
              <Tooltip title="초기화">
                <IconButton onClick={() => setNewCode("")}>
                  <RestartAltIcon fontSize="small" />
                </IconButton>
              </Tooltip>
              <Tooltip title="다운로드">
                <IconButton onClick={() => downloadText(newCode, "나의코드.txt")}>
                  <DownloadIcon fontSize="small" />
                </IconButton>
              </Tooltip>
            </Stack>
          </Box>
          <Textarea
            name="New"
            placeholder="내가 작성한 코드를 여기에 입력하세요..."
            variant="outlined"
            color="success" // warning에서 success로 변경
            minRows={15}
            maxRows={15}
            value={newCode}
            onChange={(e) => setNewCode(e.target.value)}
            sx={{
              '--Textarea-focusedHighlight': '#52c41a',
              '--Textarea-focusedThickness': '2px',
              borderColor: '#b7eb8f',
            }}
          />
        </Box>
      </Box>

      <ReactDiffViewer
        oldValue={oldCode}
        newValue={newCode}
        compareMethod={diffMethod}
        splitView={splitView}
      />
    </Box>
    </div>
  );
};

export default TextDiffViewer;
