import React, { useEffect } from 'react';
import { Helmet } from 'react-helmet-async';
import styled from 'styled-components';
//import { Link } from 'react-router-dom';

const Container = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  background: linear-gradient(135deg, #fff5f5 0%, #ffd6e7 100%);
  padding: 2rem;
`;

const Title = styled.h1`
  font-size: 3rem;
  color: #e84393;
  margin-bottom: 1rem;
  text-align: center;
`;

const Subtitle = styled.p`
  font-size: 1.2rem;
  color: #fd79a8;
  text-align: center;
  max-width: 600px;
  line-height: 1.6;
`;

const Spinner = styled.div`
  width: 50px;
  height: 50px;
  border: 5px solid #ffe0e0;
  border-top: 5px solid #e84393;
  border-radius: 50%;
  animation: spin 2s linear infinite;
  margin: 2rem 0;

  @keyframes spin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
  }
`;

function Velog() {
  useEffect(() => {
    document.title = "개발자 라이프";
  }, []);
  return (
    <Container>
      <Helmet>
        <title>개발자 라이프</title>
        <meta name="description" content="개발자 라이프" />
      </Helmet>
      <Title>준비 중</Title>
      <Subtitle>
        열심히 준비 중입니다.
      </Subtitle>
      <Spinner />
    </Container>
  );
}

export default Velog;