import React, { useEffect } from 'react';
import { Helmet } from 'react-helmet-async';
import styles from '../css/TextHelper.module.css';

function TextHelper() {
    useEffect(() => {
        document.title = "텍스트 헬퍼 - 개발자 라이프";
    }, []);
    return (
        <div className={styles.TextHelperHtml}>
            <Helmet>
                <title>텍스트 헬퍼 - 개발자 라이프</title>
            </Helmet>
            <div className={styles.TextHelperHeader}>
                <h1>텍스트 헬퍼</h1>
            </div>
            <div className={styles.TextHelperBody}>
            <div className={styles.TextHelperContainer}>

                <div className={styles.TextHelperDescription}>
                    <a className={styles.DownloadButton}
                        href={`${process.env.PUBLIC_URL}/down/TextHelper.exe`}
                        download>
                        📥다운로드
                    </a>
                </div>
                    <div className={styles.TextHelperContent}>
                        {/* 왼쪽 콘텐츠 */}
                        <div className={styles.TextHelperLeft}>
                            <img
                                className={styles.TextHelperVersionImg}
                                src={require("../img/texthelper/TextHelper1.png")}
                                alt="텍스트헬퍼 v1.0"
                            />
                            <ul className={styles.TextHelperList}>
                                <li><strong>Insert키 변경:</strong> Insert키를 다른 문구로 바꾸는 기능</li>
                                <li><strong>문자 추가:</strong> 선택한 문자 좌우에 문자를 추가하는 기능</li>
                                <li><strong>대소문자 전환:</strong> 영어 대소문자를 전환하는 기능</li>
                                <li><strong>한글/영어 전환:</strong> 한글과 영어를 전환하는 기능</li>
                                <li><strong>빈 줄 제거:</strong> 빈 줄을 제거하는 기능</li>
                            </ul>
                        </div>
                        {/* 오른쪽 콘텐츠 */}
                        <div className={styles.TextHelperRight}>
                            <img
                                className={styles.TextHelperVersionImg}
                                src={require("../img/texthelper/TextHelper2.png")}
                                alt="텍스트헬퍼 v2.0"
                            />
                            <ul className={styles.TextHelperList}>
                                <li><strong>설정 초기화:</strong> 모든 설정을 기본값으로 초기화</li>
                                <li><strong>프로그램 시작 시 최소화:</strong> 프로그램 실행 시 최소화된 상태로 시작</li>
                                <li><strong>시작 프로그램 추가/제거:</strong> Windows 시작 프로그램에 추가/제거</li>
                            </ul>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

export default TextHelper;