import React, {useEffect} from 'react';
import { Helmet } from 'react-helmet-async';
import { Link } from 'react-router-dom';
import Script from 'react-load-script';
import mainImage from '../img/homemain/main.png';
import '../css/layout.css';
import '../css/framework.css';

const HomeMain = () => {
  useEffect(() => {
    document.title = "홈페이지 - 개발자 라이프";
  }, []);
  const handleJQueryReady = () => {
    if (window.$) {
      console.log("jQuery 로드 완료:", window.$.fn.jquery);
    }
  };
  return (
    <div id="top">
      <Helmet>
        <title>홈페이지 - 개발자 라이프</title>
        <meta name="description" content="개발자 라이프 홈페이지입니다." />
      </Helmet>
      <Script
        url="https://code.jquery.com/jquery-3.6.0.min.js"
        onLoad={handleJQueryReady}
      />
      <div className="wrapper row1">
        <div className="bgded overlay"
          style={{
            backgroundImage: `url(${mainImage})`,
            backgroundPosition: "center",
            backgroundRepeat: "no-repeat",
            backgroundSize: "cover",
            height: "100%",
            width: "100%"
          }}>
          <div id="pageintro" className="hoc clear">
          </div>
        </div>
        <div className="wrapper row3">
          <main className="hoc container clear">
            <section id="introblocks">
              <ul className="nospace group btmspace-80 elements elements-four">
                <li className="one_quarter">
                  <article><Link to={'/Curriculum'}><i className="fas fa-graduation-cap"></i></Link>
                    <h6 className="heading">수업과정</h6>
                  </article>
                </li>
                <li className="one_quarter">
                  <article><Link to={'/Language'}><i className="fas fa-address-card"></i></Link>
                    <h6 className="heading">개발 언어</h6>
                  </article>
                </li>
                <li className="one_quarter">
                  <article><Link to={'/Textbook'}><i className="fas fa-book"></i></Link>
                    <h6 className="heading">수업교재</h6>
                  </article>
                </li>
                <li className="one_quarter">
                  <article><Link to={'/Map'}><i className=" fas fa-map"></i></Link>
                    <h6 className="heading">찾아오시는길</h6>
                  </article>
                </li>
              </ul>
            </section>
          </main>
        </div>
        <script src="../scripts/jquery.min.js"></script>
        <script src="../scripts/jquery.backtotop.js"></script>
        <script src="../scripts/jquery.mobilemenu.js"></script>
        <script src="../scripts/jquery.easypiechart.min.js"></script>
      </div>
    </div>
  );
};

export default HomeMain;