import React, { useEffect } from "react";
import styles from '../css/Map.module.css';
import { Helmet } from "react-helmet-async";

function Map() {
    useEffect(() => {
        document.title = "찾아오시는 길 - 개발자 라이프";
    }, []);
    return (
        <div className={styles.mapContainer}>
            <Helmet>
                <title>찾아오시는 길 - 개발자 라이프</title>
                <meta name="description" content="두류공원 지도와 유튜브 소개영상입니다." />
            </Helmet>
            <h1 className={styles.title}>두류공원 지도</h1>
            <div className={styles.mediaWrapper}>
                <iframe
                    className={styles.iframe}
                    title="Google Map"
                    src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3233.996579407322!2d128.5565047763483!3d35.849087420734016!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3565e490656677cf%3A0x9ccdc5b16eef593b!2z65GQ66WY6rO17JuQ!5e0!3m2!1sko!2skr!4v1743422044542!5m2!1sko!2skr"
                    width="800"
                    height="400"
                    style={{ border: 0 }}
                    allowFullScreen=""
                    loading="lazy"
                    referrerPolicy="no-referrer-when-downgrade"
                ></iframe>
            </div>
            <h1 className={styles.title}>두류공원 유튜브 소개영상</h1>
            <div className={styles.mediaWrapper}>
                <iframe
                    className={styles.iframe}
                    title="YouTube video player"
                    width="800"
                    height="400"
                    src="https://www.youtube.com/embed/2xPjW787r3U?si=rBOn8kO1l8eK4_vy"
                    frameBorder="0"
                    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" 
                    referrerPolicy="strict-origin-when-cross-origin"
                    allowFullScreen
                ></iframe>
            </div>
        </div>
    );
}

export default Map;