import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import Script from 'react-load-script';
import styles from '../css/TopNav.module.css'; // CSS 모듈 import

function TopNav() {
    const [isMobile, setIsMobile] = useState(false);
    const navigate = useNavigate();

    useEffect(() => {
        const handleResize = () => {
            setIsMobile(window.innerWidth <= 768);
        };

        handleResize(); // 처음에도 체크
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    const handleSelectChange = (e) => {
        const path = e.target.value;
        if (path) {
            navigate(path);
        }
    };

    return (
        <div className={styles.Topbg}>
            <div className={styles.TopNav}> {/* CSS 모듈 클래스 사용 */}
                <div className={styles.menuContainer}>
                    {!isMobile ? (
                        // PC화면: 링크 보여주기
                        <>
                            <Link to="/" className={styles.link}>프로그램 안내</Link>
                            <Link to="/RemoveEmptyLines" className={styles.link}>빈 줄 제거</Link>
                            <Link to="/TextDiffViewer" className={styles.link}>텍스트 비교</Link>
                            <Link to="/TextConverter" className={styles.link}>텍스트 변환</Link>
                            <Link to="/TextHelper" className={styles.link}>텍스트 헬퍼</Link>
                            <Link to="/CodingHelper" className={styles.link}>코딩 헬퍼</Link>
                            <Link to="/HomeMain" className={styles.link}>홈페이지</Link>
                        </>
                    ) : (
                        // 모바일화면: 콤보박스 보여주기
                        <select
                            onChange={handleSelectChange}
                            defaultValue=""
                            className={styles.select} // CSS 모듈 클래스 사용
                        >
                            <option value="" disabled>메뉴 선택</option>
                            <option value="/">프로그램 안내</option>
                            <option value="/RemoveEmptyLines">빈 줄 제거</option>
                            <option value="/TextDiffViewer">텍스트 비교</option>
                            <option value="/TextConverter">텍스트 변환</option>
                            <option value="/TextHelper">텍스트 헬퍼</option>
                            <option value="/CodingHelper">코딩 헬퍼</option>
                            <option value="/HomeMain">홈페이지</option>
                            {/* <option value="/Velog">벨로그</option> */}
                        </select>
                    )}
                </div>

                <div className={styles.translateContainer}>
                    <Script
                        url="//translate.google.com/translate_a/element.js?cb=googleTranslateElementInit"
                    />
                    <div id="google_translate_element"></div>
                </div>
            </div>
        </div>
    );
}

// 구글번역 콜백 함수
window.googleTranslateElementInit = function () {
    if (window.google && window.google.translate) {
        new window.google.translate.TranslateElement(
            {
                pageLanguage: 'ko',
                layout: window.google.translate.TranslateElement.InlineLayout.SIMPLE
            },
            'google_translate_element'
        );
    }
};

export default TopNav;