import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import reviewImg from '../img/aside/aside-top.png';
import styles from '../css/Aside.module.css'; // CSS 모듈 import
import DisplayAds from './DisplayAds'

function Aside() {
    const [isOpen, setIsOpen] = useState(false);

    return (
        <aside
            className={styles.aside} // 클래스 이름 변경
            style={{
                right: isOpen ? 0 : '-220px',
                transition: 'right 0.5s ease-in-out',
            }}
        >
            <a href="#">
                <img className={styles.asideImg} src={reviewImg} alt="리뷰" /> {/* 클래스 이름 변경 */}
            </a>
            <div className={styles.asidenav}> {/* 클래스 이름 변경 */}
                <ul>
                    {/* <li><Link to={'/Map'}>찾아오시는길(구글지도)</Link></li>
                    <li><Link to={'/Join'}>회원가입</Link></li>
                    <li><Link to={'/LoginForm'}>로그인</Link></li> */}
                    <li><Link to={'https://velog.io/@ihan1004'} target="_blank">벨로그(새 창)</Link></li>
                    <li><Link to={'/Waiting'}>이용안내</Link></li>
                    <li><Link to={'/Velog'}>회원가입</Link></li>
                    <li><Link to={'/Waiting'}>로그인</Link></li>
                    <DisplayAds />
                </ul>
            </div>
            <button
                onClick={() => setIsOpen(!isOpen)}
                className={styles.asideToggle} // 클래스 이름 변경
            >
                <img
                    src={require(`../img/aside/${isOpen ? 'close.png' : 'open.png'}`)}
                    alt={isOpen ? 'close' : 'open'}
                />
            </button>
        </aside>
    );
}

export default Aside;