import React from 'react';
import styles from '../css/Project.module.css'; // Project 전용 CSS 파일

function Project() {
    return (
        <div className={styles.projectContainer}>
            <h3 className={styles.projectHeading}>대표 프로젝트</h3>
            <div className={styles.projectGrid}>
                    <div className={styles.projectItem}>
                    <li>나이스 대국민서비스 : 유지관리 운영 사업, 기능개선 사업 참여</li>
                    <img src={require("../img/project/project1.png")} alt="나이스 대국민서비스" />
                        <div className={styles.projectCaption}>
                            <a href="https://neis.go.kr/" target="_blank" rel="noopener noreferrer">나이스 대국민서비스</a>
                        </div>
                    </div>
                    <div className={styles.projectItem}>
                    <li>모두의 한국어 : 한국어 학습관리시스템 개발 사업, 감리 사업, 고도화 사업, 유지관리 운영 사업 담당</li>
                    <img src={require("../img/project/project2.png")} alt="모두의 한국어" />
                        <div className={styles.projectCaption}>
                            <a href="https://korean.edunet.net/" target="_blank" rel="noopener noreferrer">모두의 한국어</a>
                        </div>
                    </div>
            </div>
        </div>
    );
}

export default Project;