import React, { useEffect, useRef } from 'react';
import { Helmet } from 'react-helmet-async'
import { Link } from 'react-router-dom';
import Script from 'react-load-script';
import '../css/layout.css';
import '../css/framework.css';

function Curriculum() {
    const chartsRef = useRef([]);
    const observerRef = useRef(null);
    // 차트 초기화 함수
    const initializeCharts = () => {
        if (!window.$ || !window.$.fn.easyPieChart) return;

        // 기존 차트 제거
        chartsRef.current.forEach(chart => {
            if (chart && chart.destroy) {
                chart.destroy();
            }
        });
        chartsRef.current = [];

        // 새로운 차트 초기화
        window.$('.pr-chart-ctrl').each(function() {
            const $chart = window.$(this).find('.pr-chart');
            if ($chart.length > 0 && !$chart.data('easyPieChart')) {
                const chart = $chart.easyPieChart({
                    animate: 2000,
                    scaleColor: false,
                    lineWidth: 10,
                    lineCap: 'round',
                    size: 130,
                    barColor: '#FF9900',
                    trackColor: '#f2f2f2'
                }).data('easyPieChart');
                chartsRef.current.push(chart);
            }
        });
    };

    useEffect(() => {
        document.title = "수업과정 - 개발자 라이프";
        // DOM 변화 감지를 위한 MutationObserver 설정
        observerRef.current = new MutationObserver((mutations) => {
            const chartElements = document.querySelectorAll('.pr-chart');
            if (chartElements.length > 0) {
                initializeCharts();
            }
    });

        // 초기 차트 초기화 시도
        const initialTimer = setTimeout(initializeCharts, 100);

        // Observer 시작
        observerRef.current.observe(document.body, {
            childList: true,
            subtree: true
        });

        return () => {
            clearTimeout(initialTimer);
            if (observerRef.current) {
                observerRef.current.disconnect();
            }
            // 차트 제거
            chartsRef.current.forEach(chart => {
                if (chart && chart.destroy) {
                    chart.destroy();
                }
            });
            chartsRef.current = [];
        };
    },[]);
    return (
        <div>
            <Helmet>
                <title>수업과정 - 개발자 라이프</title>
                <meta name="description" content="개발자 양성과정 수업과정 페이지입니다." />
            </Helmet>
        <div className="bgded overlay light" style={{ backgroundImage: "url('../img/code.png')" }}>
            <section id="services" className="hoc container clear">
                <div className="sectiontitle">
                    <p className="nospace font-xs">개발자 양성과정</p>
                    <h6 className="heading font-x2">수업과정</h6>
                </div>
                <ul className="nospace group elements elements-three">
                    <li className="one_third">
                        <article><a href="#"><i className="fab fa-html5"></i></a>
                            <h6 className="heading">Front</h6>
                            <p> - 최참결 선생님 -</p>
                        </article>
                    </li>
                    <li className="one_third">
                        <article><a href="#"><i className="fab fa-java"></i></a>
                            <h6 className="heading">JAVA</h6>
                            <p>- 김미강 선생님 -</p>
                        </article>
                    </li>
                    <li className="one_third">
                        <article><a href="#"><i className="fas fa-database"></i></a>
                            <h6 className="heading">SQL</h6>
                            <p>- 김미강 선생님 -</p>
                        </article>
                    </li>
                    <li className="one_third">
                        <article><a href="#"><i className="fas fa-server"></i></a>
                            <h6 className="heading">Sever</h6>
                            <p>준비 중...</p>
                        </article>
                    </li>
                    <li className="one_third">
                        <article><a href="#"><i className="fab fa-react"></i></a>
                            <h6 className="heading">Spring/React</h6>
                            <p>준비 중...</p>
                        </article>
                    </li>
                    <li className="one_third">
                        <article><a href="#"><i className="fab fa-python"></i></a>
                            <h6 className="heading">Python/BigData</h6>
                            <p>준비 중...</p>
                        </article>
                    </li>
                </ul>
            </section>
        </div>
                <div className="wrapper row3">
                    {/* 차트 컨테이너 */}
                    <section className="hoc container clear">
                        <div className="sectiontitle">
                            <p className="nospace font-xs">개발자 양성과정</p>
                            <h6 className="heading font-x2">진도율</h6>
                        </div>
                        <ul className="pr-charts nospace group center">
                            <li className="pr-chart-ctrl" data-animate="false">
                                <div className="pr-chart" data-percent="80"><i></i></div>
                                <p>프론트</p>
                            </li>
                            <li className="pr-chart-ctrl" data-animate="false">
                                <div className="pr-chart" data-percent="60"><i></i></div>
                                <p>자바</p>
                            </li>
                            <li className="pr-chart-ctrl" data-animate="false">
                                <div className="pr-chart" data-percent="60"><i></i></div>
                                <p>오라클</p>
                            </li>
                            <li className="pr-chart-ctrl" data-animate="false">
                                <div className="pr-chart" data-percent="0"><i></i></div>
                                <p>빅데이터</p>
                            </li>
                        </ul>
                    </section>
                </div>
            </div>
    );
}

export default Curriculum;