import React, { useState } from 'react';

// 두벌식 키보드 매핑 (AutoHotkey 라이브러리 참고)
const dubeolsik = {
    // 기본 자음
    r: 'ㄱ', R: 'ㄲ', s: 'ㄴ', e: 'ㄷ', E: 'ㄸ', f: 'ㄹ', a: 'ㅁ',
    q: 'ㅂ', Q: 'ㅃ', t: 'ㅅ', T: 'ㅆ', d: 'ㅇ', w: 'ㅈ', W: 'ㅉ',
    c: 'ㅊ', z: 'ㅋ', x: 'ㅌ', v: 'ㅍ', g: 'ㅎ',
    // 기본 모음
    k: 'ㅏ', o: 'ㅐ', i: 'ㅑ', O: 'ㅒ', j: 'ㅓ', p: 'ㅔ', u: 'ㅕ', P: 'ㅖ',
    h: 'ㅗ', y: 'ㅛ', n: 'ㅜ', b: 'ㅠ', m: 'ㅡ', l: 'ㅣ',
    // 복합 모음 (두 글자 조합)
    hk: 'ㅘ', ho: 'ㅙ', hl: 'ㅚ', nj: 'ㅝ', np: 'ㅞ', nl: 'ㅟ', ml: 'ㅢ'
};

// 역매핑 (한글자모 → 영어키)
const reverseDubeolsik = {
    'ㄱ': 'r', 'ㄲ': 'R', 'ㄴ': 's', 'ㄷ': 'e', 'ㄸ': 'E', 'ㄹ': 'f', 'ㅁ': 'a',
    'ㅂ': 'q', 'ㅃ': 'Q', 'ㅅ': 't', 'ㅆ': 'T', 'ㅇ': 'd', 'ㅈ': 'w', 'ㅉ': 'W',
    'ㅊ': 'c', 'ㅋ': 'z', 'ㅌ': 'x', 'ㅍ': 'v', 'ㅎ': 'g',
    'ㅏ': 'k', 'ㅐ': 'o', 'ㅑ': 'i', 'ㅒ': 'O', 'ㅓ': 'j', 'ㅔ': 'p', 'ㅕ': 'u', 'ㅖ': 'P',
    'ㅗ': 'h', 'ㅛ': 'y', 'ㅜ': 'n', 'ㅠ': 'b', 'ㅡ': 'm', 'ㅣ': 'l',
    'ㅘ': 'hk', 'ㅙ': 'ho', 'ㅚ': 'hl', 'ㅝ': 'nj', 'ㅞ': 'np', 'ㅟ': 'nl', 'ㅢ': 'ml'
};

// 한글 자모 배열 (AutoHotkey 라이브러리와 동일)
const CHOSUNG = ['ㄱ', 'ㄲ', 'ㄴ', 'ㄷ', 'ㄸ', 'ㄹ', 'ㅁ', 'ㅂ', 'ㅃ', 'ㅅ', 'ㅆ', 'ㅇ', 'ㅈ', 'ㅉ', 'ㅊ', 'ㅋ', 'ㅌ', 'ㅍ', 'ㅎ'];
const JUNGSUNG = ['ㅏ', 'ㅐ', 'ㅑ', 'ㅒ', 'ㅓ', 'ㅔ', 'ㅕ', 'ㅖ', 'ㅗ', 'ㅘ', 'ㅙ', 'ㅚ', 'ㅛ', 'ㅜ', 'ㅝ', 'ㅞ', 'ㅟ', 'ㅠ', 'ㅡ', 'ㅢ', 'ㅣ'];
const JONGSUNG = ['', 'ㄱ', 'ㄲ', 'ㄳ', 'ㄴ', 'ㄵ', 'ㄶ', 'ㄷ', 'ㄹ', 'ㄺ', 'ㄻ', 'ㄼ', 'ㄽ', 'ㄾ', 'ㄿ', 'ㅀ', 'ㅁ', 'ㅂ', 'ㅄ', 'ㅅ', 'ㅆ', 'ㅇ', 'ㅈ', 'ㅊ', 'ㅋ', 'ㅌ', 'ㅍ', 'ㅎ'];

// 영어 키 매핑 배열
const ENG_CHOSUNG = ['r', 'R', 's', 'e', 'E', 'f', 'a', 'q', 'Q', 't', 'T', 'd', 'w', 'W', 'c', 'z', 'x', 'v', 'g'];
const ENG_JUNGSUNG = ['k', 'o', 'i', 'O', 'j', 'p', 'u', 'P', 'h', 'hk', 'ho', 'hl', 'y', 'n', 'nj', 'np', 'nl', 'b', 'm', 'ml', 'l'];
const ENG_JONGSUNG = ['', 'r', 'R', 'rt', 's', 'sw', 'sg', 'e', 'f', 'fr', 'fa', 'fq', 'ft', 'fx', 'fv', 'fg', 'a', 'q', 'qt', 't', 'T', 'd', 'w', 'c', 'z', 'x', 'v', 'g'];

// 복합 모음 매핑
const DOUBLE_VOWELS = {
    'hk': 'ㅘ', 'ho': 'ㅙ', 'hl': 'ㅚ',
    'nj': 'ㅝ', 'np': 'ㅞ', 'nl': 'ㅟ', 'ml': 'ㅢ'
};

// 복합 종성 매핑
const DOUBLE_FINALS = {
    'rt': 'ㄳ', 'sw': 'ㄵ', 'sg': 'ㄶ', 'fr': 'ㄺ', 'fa': 'ㄻ', 'fq': 'ㄼ',
    'ft': 'ㄽ', 'fx': 'ㄾ', 'fv': 'ㄿ', 'fg': 'ㅀ', 'qt': 'ㅄ'
};

// 한글 조합 규칙
const isConsonant = (char) => CHOSUNG.includes(char) || JONGSUNG.includes(char);
const isVowel = (char) => JUNGSUNG.includes(char);

// 한글 조합 함수 (AutoHotkey 라이브러리 로직 기반)
const combineHangul = (first, middle, final = '') => {
    const firstIndex = CHOSUNG.indexOf(first);
    const middleIndex = JUNGSUNG.indexOf(middle);
    const finalIndex = final ? JONGSUNG.indexOf(final) : 0;

    if (firstIndex === -1 || middleIndex === -1 || (final && finalIndex === -1)) {
        return first + middle + final;
    }

    const syllableCode = 0xAC00 + (firstIndex * 21 + middleIndex) * 28 + finalIndex;
    const result = String.fromCharCode(syllableCode);

    // 유효한 한글 범위 확인
    return (result >= '가' && result <= '힣') ? result : first + middle + final;
};

// 한글 분해 함수
const disassembleHangul = (char) => {
    const code = char.charCodeAt(0);

    if (code >= 0xAC00 && code <= 0xD7A3) {
        // 완성형 한글
        const syllableIndex = code - 0xAC00;
        const chosungIndex = Math.floor(syllableIndex / (21 * 28));
        const jungsungIndex = Math.floor((syllableIndex % (21 * 28)) / 28);
        const jongsungIndex = syllableIndex % 28;

        let result = [CHOSUNG[chosungIndex], JUNGSUNG[jungsungIndex]];
        if (jongsungIndex > 0) {
            result.push(JONGSUNG[jongsungIndex]);
        }
        return result;
    } else if (code >= 0x3131 && code <= 0x318E) {
        // 자모
        return [char];
    }
    return [char];
};

// 영어 → 한글 변환 함수 (개선된 버전)
const englishToHangul = (text) => {
    let processed = text;

    // 1. 복합 모음 먼저 처리
    Object.entries(DOUBLE_VOWELS).forEach(([eng, kor]) => {
        processed = processed.replace(new RegExp(eng, 'g'), kor);
    });

    // 2. 복합 종성 처리 (모음 뒤가 아닌 경우)
    Object.entries(DOUBLE_FINALS).forEach(([eng, kor]) => {
        processed = processed.replace(new RegExp(eng + '(?![ㅏ-ㅣ])', 'g'), kor);
    });

    // 3. 기본 자모 변환
    Object.entries(dubeolsik).forEach(([eng, kor]) => {
        if (eng.length === 1) { // 단일 문자만 처리
            processed = processed.replace(new RegExp(eng, 'g'), kor);
        }
    });

    // 4. 한글 조합
    const chars = processed.split('');
    let result = '';
    let tempJamos = [];

    for (let i = 0; i < chars.length; i++) {
        const char = chars[i];

        if (isConsonant(char) || isVowel(char)) {
            tempJamos.push(char);
        } else {
            // 자모가 아닌 문자가 나오면 기존 자모들 조합
            if (tempJamos.length > 0) {
                result += combineJamos(tempJamos);
                tempJamos = [];
            }
            result += char;
        }
    }

    // 마지막에 남은 자모들 처리
    if (tempJamos.length > 0) {
        result += combineJamos(tempJamos);
    }

    return result;
};

// 자모 배열을 한글로 조합하는 함수
const combineJamos = (jamos) => {
    if (jamos.length === 0) return '';

    let result = '';
    let i = 0;

    while (i < jamos.length) {
        const first = jamos[i];
        const middle = jamos[i + 1];
        const final = jamos[i + 2];

        // 초성 + 중성 조합 가능한 경우
        if (CHOSUNG.includes(first) && middle && JUNGSUNG.includes(middle)) {
            // 종성이 있는지 확인
            if (final && JONGSUNG.includes(final)) {
                result += combineHangul(first, middle, final);
                i += 3;
            } else {
                result += combineHangul(first, middle);
                i += 2;
            }
        } else {
            result += first;
            i++;
        }
    }

    return result;
};

// 한글 → 영어 변환 함수
const hangulToEnglish = (text) => {
    const chars = text.split('');
    let result = '';

    chars.forEach(char => {
        if (char >= '가' && char <= '힣') {
            // 완성형 한글 분해
            const jamos = disassembleHangul(char);
            jamos.forEach(jamo => {
                const chosungIndex = CHOSUNG.indexOf(jamo);
                const jungsungIndex = JUNGSUNG.indexOf(jamo);
                const jongsungIndex = JONGSUNG.indexOf(jamo);

                if (chosungIndex !== -1) {
                    result += ENG_CHOSUNG[chosungIndex];
                } else if (jungsungIndex !== -1) {
                    result += ENG_JUNGSUNG[jungsungIndex];
                } else if (jongsungIndex !== -1) {
                    result += ENG_JONGSUNG[jongsungIndex];
                } else {
                    result += jamo;
                }
            });
        } else if (char >= 'ㄱ' && char <= 'ㅣ') {
            // 단일 자모
            const engKey = reverseDubeolsik[char];
            result += engKey || char;
        } else {
            result += char;
        }
    });

    return result;
};

// 대소문자 변환
const convertCase = (text) =>
    text.split('')
        .map(char => char === char.toLowerCase() ? char.toUpperCase() : char.toLowerCase())
        .join('');

// 복사 함수
const copyToClipboard = async (text) => {
    try {
        await navigator.clipboard.writeText(text);
        return true;
    } catch (err) {
        return false;
    }
};

const TextConverter = () => {
    const [input, setInput] = useState('');
    const [converted, setConverted] = useState('');
    const [message, setMessage] = useState('');

    const handleConvert = (type) => {
        if (!input.trim()) {
            setMessage('⚠️ 입력 텍스트를 입력해주세요');
            return;
        }

        let result = '';
        switch (type) {
            case 'case':
                result = convertCase(input);
                setMessage('✅ 대소문자 전환 완료');
                break;
            case 'hanToEng':
                result = hangulToEnglish(input);
                setMessage('✅ 한글 → 영어 변환 완료');
                break;
            case 'engToHan':
                result = englishToHangul(input);
                setMessage('✅ 영어 → 한글 변환 완료');
                break;
            default:
                result = input;
        }
        setConverted(result);
    };

    const handleReset = () => {
        setInput('');
        setConverted('');
        setMessage('');
    };

    const handleCopy = async () => {
        if (!converted) {
            setMessage('⚠️ 복사할 텍스트가 없습니다');
            return;
        }

        const success = await copyToClipboard(converted);
        setMessage(success ? '✅ 클립보드에 복사되었습니다' : '❌ 복사에 실패했습니다');
    };

    // CSS styles object
    const styles = {
        page: {
            backgroundColor: '#ffffff',
            minHeight: '100vh',
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'flex-start',
            padding: '4rem 1rem',
            boxSizing: 'border-box'
        },
        wrapper: {
            width: '100%',
            maxWidth: '800px',
            backgroundColor: '#ffffff',
            borderRadius: '8px',
            boxShadow: '0 2px 6px rgba(0, 0, 0, 0.1)',
            padding: '2rem',
            boxSizing: 'border-box'
        },
        title: {
            fontSize: '2rem',
            fontWeight: '700',
            marginBottom: '1.5rem',
            color: '#222222',
            textAlign: 'center'
        },
        columns: {
            display: 'flex',
            gap: '2rem',
            flexWrap: 'wrap',
            marginBottom: '1.5rem'
        },
        textarea: {
            flex: '1 1 45%',
            minHeight: '200px',
            padding: '14px',
            border: '1px solid #cccccc',
            borderRadius: '6px',
            fontSize: '16px',
            lineHeight: '1.5',
            resize: 'vertical',
            boxSizing: 'border-box'
        },
        outputArea: {
            flex: '1 1 45%',
            display: 'flex',
            flexDirection: 'column',
            justifyContent: 'space-between'
        },
        resultTitle: {
            fontSize: '1.25rem',
            fontWeight: '600',
            marginBottom: '0.5rem',
            color: '#333333',
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center'
        },
        resultBox: {
            backgroundColor: '#f9f9f9',
            padding: '1rem',
            border: '1px solid #ddd',
            borderRadius: '6px',
            minHeight: '200px',
            whiteSpace: 'pre-wrap',
            fontSize: '16px',
            color: '#222222'
        },
        buttonGroup: {
            display: 'flex',
            gap: '1rem',
            justifyContent: 'center',
            marginBottom: '2rem',
            flexWrap: 'wrap'
        },
        button: {
            padding: '12px 20px',
            fontSize: '16px',
            fontWeight: '600',
            border: '2px solid transparent',
            borderRadius: '4px',
            cursor: 'pointer',
            transition: 'all 0.2s ease'
        },
        buttonCase: {
            backgroundColor: '#1976d2',
            color: '#ffffff'
        },
        buttonHangul: {
            backgroundColor: '#43a047',
            color: '#ffffff'
        },
        buttonReset: {
            backgroundColor: '#d32f2f',
            color: '#ffffff',
            borderColor: '#d32f2f'
        },
        message: {
            marginTop: '1rem',
            textAlign: 'center',
            fontWeight: '500',
            fontSize: '1rem',
            animation: 'fadeIn 0.4s ease'
        },
        messageSuccess: {
            color: '#007bff'
        },
        messageError: {
            color: '#d32f2f'
        },
        copyButton: {
            fontSize: '14px',
            color: '#1976d2',
            backgroundColor: 'transparent',
            border: 'none',
            cursor: 'pointer',
            textDecoration: 'underline'
        },
        usageGuide: {
            marginTop: '2rem',
            padding: '1rem',
            backgroundColor: '#f5f5f5',
            borderRadius: '6px',
            fontSize: '14px',
            color: '#666666'
        }
    };

    return (
        <div style={styles.page}>
            <div style={styles.wrapper}>
                <h1 style={styles.title}>텍스트 변환기</h1>

                <div style={styles.columns}>
                    <textarea
                        style={styles.textarea}
                        value={input}
                        onChange={e => setInput(e.target.value)}
                        placeholder="변환할 텍스트를 입력하세요..."
                    />
                    <div style={styles.outputArea}>
                        <div style={styles.resultTitle}>
                            변환 결과
                            {converted && (
                                <button
                                    style={styles.copyButton}
                                    onClick={handleCopy}
                                >
                                    📋 복사
                                </button>
                            )}
                        </div>
                        <div style={styles.resultBox}>
                            {converted || '변환 결과가 여기에 표시됩니다'}
                        </div>
                    </div>
                </div>

                <div style={styles.buttonGroup}>
                    <button
                        onClick={() => handleConvert('hanToEng')}
                        style={{ ...styles.button, ...styles.buttonHangul }}
                    >
                        한글 → 영어
                    </button>
                    <button
                        onClick={() => handleConvert('engToHan')}
                        style={{ ...styles.button, ...styles.buttonHangul }}
                    >
                        영어 → 한글
                    </button>
                    <button
                        onClick={() => handleConvert('case')}
                        style={{ ...styles.button, ...styles.buttonCase }}
                    >
                        영어 대소문자 변환
                    </button>
                    <button
                        onClick={handleReset}
                        style={{ ...styles.button, ...styles.buttonReset }}
                    >
                        초기화
                    </button>
                </div>

                {message && (
                    <div style={{
                        ...styles.message,
                        ...(message.includes('⚠️') || message.includes('❌')
                            ? styles.messageError
                            : styles.messageSuccess)
                    }}>
                        {message}
                    </div>
                )}

                <div style={styles.usageGuide}>
                    <strong>사용법:</strong><br />
                    • <strong>한글 → 영어:</strong> 한글을 두벌식 키보드 영어 자판으로 변환<br />
                    • <strong>영어 → 한글:</strong> 영어를 두벌식 키보드 한글로 변환<br />
                    • <strong>대소문자 변환:</strong> 영어 대문자는 소문자로, 소문자는 대문자로 변환<br />
                </div>
            </div>
        </div>
    );
};

export default TextConverter;