import React, { useEffect } from 'react';
import { Helmet } from 'react-helmet-async';
import { motion, useAnimation } from 'framer-motion';
import styles from '../css/Language.module.css';

function Language() {
    const controls = useAnimation();

    useEffect(() => {
        document.title = "개발 언어 - 개발자 라이프";
        controls.start({ opacity: 1, y: 0, transition: { duration: 0.5 } });
    }, [controls]);

    const items = [
        {
            title: "FRONT END",
            icons: [
                { icon: "fab fa-html5", name: "HTML" },
                { icon: "fab fa-css3", name: "CSS" },
                { icon: "fab fa-js", name: "JavaScript" },
                { icon: "fab fa-react", name: "React" },
                // { icon: "fab fa-node", name: "Node.js" },
                // { icon: "fab fa-npm", name: "NPM" },
                // { icon: "fab fa-vuejs", name: "Vue.js" },
            ]
        },
        {
            title: "BACK END",
            icons: [
                { icon: "fab fa-java", name: "JAVA" },
                { icon: "fas fa-leaf", name: "Spring" },
                { icon: "fas fa-database", name: "Oracle" },
                { icon: "fas fa-database", name: "MySQL" },
            ]
        },
        {
            title: "BigData/Project",
            icons: [
                { icon: "fab fa-python", name: "Python" },
                { icon: "fab fa-github", name: "Github" },
            ]
        },
    ];

    return (
        <div className={styles.container}>
            <Helmet>
                <title>개발 언어 - 개발자 라이프</title>
                </Helmet>
            <div className={styles.sectionTitle}>
                <p></p>
                <h6>개발 언어</h6>
            </div>
            <div className={styles.boxContainer}>
                {items.map((item, index) => (
                    <motion.div
                        key={index}
                        className={styles.box}
                        custom={index}
                        initial={{ opacity: 0, y: 50 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ duration: 0.5, delay: index * 0.2 }}
                    >
                        <h6>{item.title}</h6>
                        <div className={styles.iconGrid}>
                            {item.icons.map((tech, i) => (
                                <div key={i} className={styles.iconItem}>
                                    <i className={tech.icon}></i>
                                    <span>{tech.name}</span>
                                </div>
                            ))}
                        </div>
                    </motion.div>
                ))}
            </div>
        </div>
    );
}

export default Language;