import React, { useEffect, useRef } from 'react';
import { Helmet } from 'react-helmet-async';
import * as THREE from 'three';
import styles from '../css/TextBook.module.css';

const Book = () => {
  useEffect(() => {
    document.title = "수업 교재 - 개발자 라이프";
  }, []);

  const books = [
    {
      id: 1,
      title: '자바 교재',
      bookCovers: {
        front: `${process.env.PUBLIC_URL}/images/book/book11.jpg`,
        back: `${process.env.PUBLIC_URL}/images/book/book12.jpg`,
        spine: `${process.env.PUBLIC_URL}/images/book/book13.jpg`,
      },
    },
    {
      id: 2,
      title: '오라클 교재',
      bookCovers: {
        front: `${process.env.PUBLIC_URL}/images/book/book21.jpg`,
        back: `${process.env.PUBLIC_URL}/images/book/book22.jpg`,
        spine: `${process.env.PUBLIC_URL}/images/book/book23.jpg`,
      },
    },
    {
      id: 3,
      title: '프론트 교재',
      bookCovers: {
        front: `${process.env.PUBLIC_URL}/images/book/book31.jpg`,
        back: `${process.env.PUBLIC_URL}/images/book/book32.jpg`,
        spine: `${process.env.PUBLIC_URL}/images/book/book33.jpg`,
      },
    },
  ];

  const style = {
    width: 300,
    height: 400,
    background: '#ffffff',
    margin: '0px auto',
  };

  return ( // ✅ JSX 반환하도록 수정
    <div className={styles.textbookContainer}>
      <Helmet>
        <title>수업 교재 - 개발자 라이프</title>
      </Helmet>
      <div className={styles.header}>
        <h1 className={styles.title}>수업 교재</h1>
      </div>
      <div className={styles.bookGrid}>
        {books.map((book) => (
          <div key={book.id} className={styles.bookCard}>
            <h2 className={styles.bookTitle}>{book.title}</h2>
            <div className={styles.bookInfo}>
              <Textbook bookCovers={book.bookCovers} style={style} />
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

const Textbook = ({ bookCovers, style = { width: 800, height: 600, background: '#ffffff' } }) => {
  const mountRef = useRef(null);

  useEffect(() => {
    const aspect = style.width / style.height;

    const getBookMaterials = (urlMap) => {
      if (!urlMap) {
        const defaultMaterial = new THREE.MeshBasicMaterial({ color: 0xffffff });
        return Array(6).fill(defaultMaterial);
      }

      const defaultMaterial = new THREE.MeshBasicMaterial({ color: 0xcccccc });
      const textureLoader = new THREE.TextureLoader();

      const loadTexture = (url) => {
        if (!url) return defaultMaterial;
        const texture = textureLoader.load(
          url,
          (tex) => {
            tex.minFilter = THREE.LinearFilter;
            tex.magFilter = THREE.LinearFilter;
          },
          undefined,
          (err) => console.error(`Error loading texture ${url}:`, err)
        );
        return new THREE.MeshBasicMaterial({ map: texture });
      };

      const materials = [
        defaultMaterial, // right
        urlMap.spine ? loadTexture(urlMap.spine) : defaultMaterial, // left
        defaultMaterial, // top
        defaultMaterial, // bottom
        urlMap.front ? loadTexture(urlMap.front) : defaultMaterial, // front
        urlMap.back ? loadTexture(urlMap.back) : defaultMaterial,  // back
      ];

      return materials;
    };

    const refCurrent = mountRef.current;
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(style.background);

    const plane = new THREE.Mesh(
      new THREE.PlaneGeometry(500, 500),
      (() => {
        const m = new THREE.ShadowMaterial();
        m.opacity = 0.5;
        return m;
      })()
    );
    plane.receiveShadow = true;
    scene.add(plane);

    const light = new THREE.DirectionalLight(0xffffff, 0.3);
    light.position.set(-10, 10, 10);
    light.castShadow = true;
    scene.add(light);

    const cube = new THREE.Mesh(
      new THREE.BoxGeometry(3.5, 5, 0.5),
      getBookMaterials(bookCovers)
    );
    cube.castShadow = true;
    scene.add(cube);

    let isMouseOver = false;
    refCurrent.addEventListener('mouseover', () => { isMouseOver = true; });
    refCurrent.addEventListener('mouseleave', () => { isMouseOver = false; });

    let degrees = 90;
    const distance = 6;
    const camera = new THREE.PerspectiveCamera(70, aspect, 1, 1000);
    camera.position.set(
      Math.cos(degrees * Math.PI / 180) * distance,
      0,
      Math.sin(degrees * Math.PI / 180) * distance
    );

    const renderer = new THREE.WebGLRenderer();
    renderer.shadowMap.enabled = true;
    renderer.setPixelRatio(window.devicePixelRatio);
    renderer.setSize(style.width, style.height);
    refCurrent.appendChild(renderer.domElement);

    const rotate = () => {
      if (degrees < 270) {
        degrees += 2;
        const rad = degrees * Math.PI / 180;
        camera.position.x = Math.cos(rad) * distance;
        camera.position.z = Math.sin(rad) * distance;
      }
    };

    const rotateBack = () => {
      if (degrees > 90) {
        degrees -= 2;
        const rad = degrees * Math.PI / 180;
        camera.position.x = Math.cos(rad) * distance;
        camera.position.z = Math.sin(rad) * distance;
      }
    };

    const animate = () => {
      requestAnimationFrame(animate);
      isMouseOver ? rotate() : rotateBack();
      camera.lookAt(scene.position);
      renderer.render(scene, camera);
    };

    animate();

    return () => {
      refCurrent.removeChild(renderer.domElement); // ✅ clean-up
    };

  }, [bookCovers, style]); // ✅ 의존성 배열

  return <div ref={mountRef} style={style} />;
};

export default Book;